package com.shadow.app
import androidx.room.*
import kotlinx.coroutines.flow.Flow
@Entity(tableName="pending_commands",indices=[Index(value=["accountId","subjectId","commandId"],unique=true)]) data class PendingCommand(@PrimaryKey val commandId:String,val accountId:String,val subjectId:String,val capability:String,val body:String,val state:String="pending",val attempts:Int=0,val createdAt:Long=System.currentTimeMillis())
@Entity(tableName="pending_attachments",indices=[Index(value=["accountId","subjectId","commandId"],unique=true)]) data class PendingAttachment(@PrimaryKey val id:String,val accountId:String,val subjectId:String,val commandId:String,val localPath:String,val mediaType:String,val state:String="pending",val createdAt:Long=System.currentTimeMillis())
@Dao interface CommandDao{@Insert(onConflict=OnConflictStrategy.IGNORE)suspend fun enqueue(value:PendingCommand):Long;@Query("select * from pending_commands where accountId=:account and subjectId=:subject and state='pending' order by createdAt")suspend fun pending(account:String,subject:String):List<PendingCommand>;@Query("select * from pending_commands where accountId=:account and subjectId=:subject order by createdAt desc")fun observe(account:String,subject:String):Flow<List<PendingCommand>>;@Query("select count(*) from pending_commands where accountId='' and state='needs_account'")fun observeRecoverableCount():Flow<Int>;@Query("update pending_commands set accountId=:account,subjectId=:subject,state='pending' where accountId='' and state='needs_account'")suspend fun recoverToAccount(account:String,subject:String):Int;@Query("update pending_commands set state=:state,attempts=attempts+1 where commandId=:id")suspend fun mark(id:String,state:String);@Insert(onConflict=OnConflictStrategy.IGNORE)suspend fun enqueueAttachment(value:PendingAttachment):Long;@Query("select * from pending_attachments where accountId=:account and subjectId=:subject and state='pending' order by createdAt")suspend fun pendingAttachments(account:String,subject:String):List<PendingAttachment>;@Query("update pending_attachments set state=:state where id=:id")suspend fun markAttachment(id:String,state:String)}
@Database(entities=[PendingCommand::class,PendingAttachment::class],version=4,exportSchema=true)abstract class ShadowDatabase:RoomDatabase(){abstract fun commands():CommandDao}
